import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import {
  Type,
  createAssistantMessageEventStream,
  createFauxCore,
  fauxAssistantMessage,
  fauxText,
  fauxThinking,
  fauxToolCall,
} from "@earendil-works/pi-ai";
import {
  InMemorySessionStorage,
  Session,
  agentLoop,
  buildSessionContext,
  estimateTokens,
  prepareCompaction,
  serializeConversation,
} from "@earendil-works/pi-agent-core";
import {
  ClientMessageDecoder,
  FrameDecoder,
  encodeClientMessage,
  parseClientMessage,
} from "@earendil-works/pi-protocol";

const outputDirectory = process.argv[2];
if (!outputDirectory) throw new Error("usage: node extract-pi-fixtures.mjs <output-directory>");
await mkdir(outputDirectory, { recursive: true });

const FIXED_TIME = 1704067200000;
const originalNow = Date.now;
Date.now = () => FIXED_TIME;
try {
  await writeFixture("provider-faux-stream.json", await providerFixture());
  await writeFixture("agent-loop-tool-run.json", await agentLoopFixture());
  await writeFixture("session-tool-run-log.json", await sessionFixture());
  await writeFixture("compaction-prepare.json", compactionFixture());
  await writeFixture("protocol-client-hello.json", protocolFixture());
} finally {
  Date.now = originalNow;
}

async function providerFixture() {
  const input = {
    context: {
      systemPrompt: "Answer with one tool call.",
      messages: [{ role: "user", content: "Read status", timestamp: FIXED_TIME }],
      tools: [{
        name: "read_status",
        description: "Read a status file",
        parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
      }],
    },
    modelOptions: { maxTokens: 64, temperature: 0, sessionId: "session-fixture", cacheRetention: "none" },
    response: {
      content: [
        { type: "thinking", thinking: "check" },
        { type: "text", text: "Checking." },
        { type: "toolCall", id: "tool-call-1", name: "read_status", arguments: { path: "status.txt" } },
      ],
      stopReason: "toolUse",
      timestamp: FIXED_TIME,
    },
  };
  const faux = createFauxCore({
    api: "faux-fixture",
    provider: "faux",
    models: [{ id: "faux-1", name: "Faux Fixture", reasoning: true }],
    tokenSize: { min: 100, max: 100 },
  });
  faux.setResponses([
    fauxAssistantMessage([
      fauxThinking("check"),
      fauxText("Checking."),
      fauxToolCall("read_status", { path: "status.txt" }, { id: "tool-call-1" }),
    ], { stopReason: "toolUse", timestamp: FIXED_TIME }),
  ]);
  const stream = faux.stream(faux.getModel(), input.context, input.modelOptions);
  const events = [];
  for await (const event of stream) events.push(event);
  return envelope("pi-provider-faux-stream", "provider", "@earendil-works/pi-ai", input, {
    events,
    finalMessage: await stream.result(),
    providerState: faux.state,
  }, {
    eventTypes: [
      "start", "thinking_start", "thinking_delta", "thinking_end", "text_start", "text_delta", "text_end",
      "toolcall_start", "toolcall_delta", "toolcall_end", "done",
    ],
    toolCallDiscriminant: "toolCall",
  });
}

async function agentLoopFixture() {
  const input = {
    prompt: { role: "user", content: "Read status", timestamp: FIXED_TIME },
    context: { systemPrompt: "Use the status tool.", messages: [] },
    tool: {
      name: "read_status",
      label: "Read status",
      description: "Read a status file",
      parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
    },
    model: { id: "faux-1", api: "faux-fixture", provider: "faux", maxTokens: 16384 },
  };
  const faux = createFauxCore({
    api: "faux-fixture",
    provider: "faux",
    models: [{ id: "faux-1", name: "Faux Fixture" }],
    tokenSize: { min: 100, max: 100 },
  });
  faux.setResponses([
    fauxAssistantMessage(fauxToolCall("read_status", { path: "status.txt" }, { id: "tool-call-1" }), {
      stopReason: "toolUse", timestamp: FIXED_TIME,
    }),
    fauxAssistantMessage("Status is ready.", { timestamp: FIXED_TIME }),
  ]);
  const toolSchema = Type.Object({ path: Type.String() });
  const tool = {
    ...input.tool,
    parameters: toolSchema,
    async execute(_toolCallId, args) {
      return { content: [{ type: "text", text: "ready" }], details: { path: args.path } };
    },
  };
  const context = { ...input.context, messages: [], tools: [tool] };
  const events = [];
  const stream = agentLoop(
    [input.prompt],
    context,
    { model: faux.getModel(), convertToLlm: (messages) => messages },
    undefined,
    faux.stream,
  );
  for await (const event of stream) events.push(event);
  return envelope("pi-agent-loop-tool-run", "agent-loop", "@earendil-works/pi-agent-core", input, {
    events,
    messages: await stream.result(),
  }, {
    finalMessageRoles: ["user", "assistant", "toolResult", "assistant"],
    toolCallId: "tool-call-1",
  });
}

async function sessionFixture() {
  const input = {
    sessionId: "session-1",
    lane: "main",
    runId: "run-1",
    entries: ["entry-user-1", "entry-assistant-1", "entry-tool-result-1"],
  };
  const storage = new InMemorySessionStorage({ id: input.sessionId, createdAt: FIXED_TIME });
  const session = new Session(storage, { idGenerator: { next: () => { throw new Error("unexpected generated id"); } } });
  await session.appendRecord({
    type: "operation_started", id: input.runId, lane: input.lane, sourceLeafId: null,
    intent: {
      kind: "run",
      originalPrompt: [{ role: "user", content: "Read status", timestamp: FIXED_TIME }],
      initialMessages: [{
        type: "message", id: "entry-user-1",
        message: { role: "user", content: "Read status", timestamp: FIXED_TIME },
      }],
    },
  });
  await session.appendEntry({
    type: "message", id: "entry-user-1",
    message: { role: "user", content: "Read status", timestamp: FIXED_TIME },
  }, input.lane);
  await session.appendRecord({
    type: "step_attempt", id: "record-attempt-1", lane: input.lane, runId: input.runId,
    step: "assistant", attempt: 1, resultEntryId: "entry-assistant-1",
  });
  await session.appendEntry({
    type: "message", id: "entry-assistant-1",
    message: assistantMessage([
      { type: "text", text: "Checking." },
      { type: "toolCall", id: "tool-call-1", name: "read_status", arguments: { path: "status.txt" } },
    ], "toolUse"),
  }, input.lane);
  await session.appendRecord({
    type: "tool_started", id: "record-tool-1", lane: input.lane, runId: input.runId,
    assistantEntryId: "entry-assistant-1", toolIndex: 0, toolCallId: "tool-call-1", toolName: "read_status",
    effectiveArgs: { path: "status.txt" }, resultEntryId: "entry-tool-result-1", replay: "safe",
  });
  await session.appendEntry({
    type: "message", id: "entry-tool-result-1",
    message: {
      role: "toolResult", toolCallId: "tool-call-1", toolName: "read_status",
      content: [{ type: "text", text: "ready" }], details: { path: "status.txt" }, isError: false,
      timestamp: FIXED_TIME,
    },
  }, input.lane);
  await session.appendRecord({
    type: "operation_finished", id: "record-finish-1", lane: input.lane, runId: input.runId, outcome: "completed",
  });
  return envelope("pi-session-tool-run-log", "session", "@earendil-works/pi-agent-core", input, {
    log: await session.getLog(),
    leafId: await session.getLeafId(),
    openOperations: await session.findOpenOperations(input.lane),
  }, {
    logKinds: ["record", "entry", "record", "entry", "record", "entry", "record"],
    entryRoles: ["user", "assistant", "toolResult"],
  });
}

function compactionFixture() {
  const input = {
    settings: { enabled: true, reserveTokens: 64, keepRecentTokens: 6 },
    entries: compactionEntries(),
  };
  const result = prepareCompaction(input.entries, input.settings);
  if (!result.ok || result.value === undefined) throw new Error("Pi did not prepare the fixture compaction");
  const preparation = result.value;
  const context = buildSessionContext(input.entries);
  const serializablePreparation = {
    ...preparation,
    fileOps: {
      read: [...preparation.fileOps.read].sort(),
      written: [...preparation.fileOps.written].sort(),
      edited: [...preparation.fileOps.edited].sort(),
    },
  };
  return envelope("pi-compaction-prepare", "compaction", "@earendil-works/pi-agent-core", input, {
    preparation: serializablePreparation,
    context,
    tokenEstimates: context.messages.map((message) => estimateTokens(message)),
    serializedConversation: serializeConversation(context.messages),
  }, {
    retainsTail: preparation.retainedTail.length > 0,
    settingsRoundTrip: preparation.settings,
  });
}

function protocolFixture() {
  const input = { message: { type: "hello", version: 1 }, fragmentAt: 7 };
  const parsed = parseClientMessage(input.message);
  const framed = encodeClientMessage(parsed);
  const decoder = new ClientMessageDecoder();
  const decoded = [
    ...decoder.push(framed.subarray(0, input.fragmentAt)),
    ...decoder.push(framed.subarray(input.fragmentAt)),
  ];
  decoder.end();
  const payloads = new FrameDecoder().push(framed);
  return envelope("pi-protocol-client-hello", "protocol", "@earendil-works/pi-protocol", input, {
    parsed,
    decoded,
    payloadHex: Buffer.from(payloads[0]).toString("hex"),
    frameHex: Buffer.from(framed).toString("hex"),
    frameBase64: Buffer.from(framed).toString("base64"),
  }, {
    payloadHex: "a264747970656568656c6c6f6776657273696f6e01",
    frameHex: "00000015a264747970656568656c6c6f6776657273696f6e01",
  });
}

function compactionEntries() {
  const usage = { input: 30, output: 10, cacheRead: 0, cacheWrite: 0, totalTokens: 40,
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
  const user = (id, parentId, seq, text) => ({
    type: "message", id, parentId, seq, timestamp: FIXED_TIME,
    message: { role: "user", content: text, timestamp: FIXED_TIME },
  });
  const assistant = (id, parentId, seq, text) => ({
    type: "message", id, parentId, seq, timestamp: FIXED_TIME,
    message: assistantMessage([{ type: "text", text }], "stop", usage),
  });
  const firstUser = user("entry-u1", null, 1, "First question with enough text.");
  const firstAssistant = assistant("entry-a1", firstUser.id, 2, "First answer with enough text.");
  const secondUser = user("entry-u2", firstAssistant.id, 3, "Second question with enough text.");
  const secondAssistant = assistant("entry-a2", secondUser.id, 4, "Second answer with enough text.");
  const thirdUser = user("entry-u3", secondAssistant.id, 5, "Latest question.");
  const thirdAssistant = assistant("entry-a3", thirdUser.id, 6, "Latest answer.");
  return [firstUser, firstAssistant, secondUser, secondAssistant, thirdUser, thirdAssistant];
}

function assistantMessage(content, stopReason, usage = zeroUsage()) {
  return {
    role: "assistant", content, api: "faux-fixture", provider: "faux", model: "faux-1",
    usage, stopReason, timestamp: FIXED_TIME,
  };
}

function zeroUsage() {
  return { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } };
}

function envelope(fixtureId, domain, packageName, input, raw, assertion) {
  return {
    schemaVersion: "1.0",
    fixtureId,
    domain,
    source: {
      repository: "https://github.com/earendil-works/pi.git",
      revision: "6c87d9a026677b601e8278030dcf1ad97fe0bd86",
      package: packageName,
      packageVersion: "0.84.3",
    },
    input,
    raw,
    assertion,
  };
}

async function writeFixture(name, value) {
  await writeFile(path.join(outputDirectory, name), `${JSON.stringify(value, null, 2)}\n`);
}
